// src/components/ROI/tabs/SavingsTabs.js
import React from "react";
import { NavLink, Outlet, useOutletContext } from "react-router-dom";

export default function SavingsTabs() {
  const ctx = useOutletContext(); // pass intake/project details to children if needed

  const onSave = () => {
    // Optional: central Save for "Savings" parent
    console.log("Save (Savings parent):", ctx);
  };

  return (
    <div>
      {/* Save button for the Savings main tab */}
      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}>
        <button className="btn-red" onClick={onSave}>&lt;Save&gt;</button>
      </div>

      {/* 3 sub-tabs under Savings */}
      <div className="roi-tabs" style={{ marginBottom: 10 }}>
        <NavLink className="roi-tab" to="project">Project Savings</NavLink>
        <NavLink className="roi-tab" to="initiative">Initiative Savings</NavLink>
        <NavLink className="roi-tab" to="soa">SOA Savings</NavLink>
      </div>

      {/* Child content */}
      <div className="roi-tab-panel">
        <Outlet context={ctx} />
      </div>
    </div>
  );
}
